      out.write("<script>\r\n");
      out.write("    function closeAllActionMenus(exceptMenu) {\r\n");
      out.write("        document.querySelectorAll('.action-menu.open').forEach(function(menu) {\r\n");
      out.write("            if (!exceptMenu || menu !== exceptMenu) {\r\n");
      out.write("                menu.classList.remove('open');\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    }\r\n");
      out.write("    function toggleActionMenu(event, triggerBtn) {\r\n");
      out.write("        event.stopPropagation();\r\n");
      out.write("        var menu = triggerBtn.closest('.action-menu');\r\n");
      out.write("        if (!menu) return;\r\n");
      out.write("        var shouldOpen = !menu.classList.contains('open');\r\n");
      out.write("        closeAllActionMenus();\r\n");
      out.write("        if (shouldOpen) {\r\n");
      out.write("            menu.classList.add('open');\r\n");
      out.write("        }\r\n");
      out.write("    }\r\n");
      out.write("    function confirmDelete(userId, username) {\r\n");
      out.write("        closeAllActionMenus();\r\n");
