      out.write("    }\r\n");
      out.write("    function confirmReset(userId, username) {\r\n");
      out.write("        closeAllActionMenus();\r\n");
      out.write("        document.getElementById('resetUserId').value = userId;\r\n");
      out.write("        document.getElementById('resetModalMsg').textContent =\r\n");
      out.write("            'Kata laluan sedia ada \"' + username + '\" akan digantikan dengan kata laluan sementara yang dijana secara rawak.';\r\n");
      out.write("        document.getElementById('resetModal').classList.add('active');\r\n");
      out.write("    }\r\n");
      out.write("    function confirmRole(userId, username, currentRole) {\r\n");
      out.write("        closeAllActionMenus();\r\n");
      out.write("        document.getElementById('roleUserId').value = userId;\r\n");
