      out.write("            'Pilih peranan baharu untuk pengguna \"' + username + '\".';\r\n");
      out.write("        document.getElementById('roleSelect').value = currentRole === 'ADMIN' ? 'ADMIN' : 'USER';\r\n");
      out.write("        document.getElementById('roleModal').classList.add('active');\r\n");
      out.write("    }\r\n");
      out.write("    function confirmPhone(userId, username, currentPhone) {\r\n");
      out.write("        closeAllActionMenus();\r\n");
