      out.write("            'Kemaskini nombor telefon untuk pengguna \"' + username + '\".';\r\n");
      out.write("        document.getElementById('phoneInput').value = currentPhone || '';\r\n");
      out.write("        document.getElementById('phoneModal').classList.add('active');\r\n");
      out.write("    }\r\n");
      out.write("    function confirmEmail(userId, username, currentEmail) {\r\n");
      out.write("        closeAllActionMenus();\r\n");
      out.write("        document.getElementById('emailUserId').value = userId;\r\n");
      out.write("        document.getElementById('emailModalMsg').textContent =\r\n");
