      out.write("        document.getElementById('emailInput').value = currentEmail || '';\r\n");
      out.write("        document.getElementById('emailModal').classList.add('active');\r\n");
      out.write("    }\r\n");
      out.write("    function closeModal(id) {\r\n");
      out.write("        document.getElementById(id).classList.remove('active');\r\n");
